```json
{
  "object": "hermes.session.chat.completion",
  "session_id": "sa-analysis-001",
  "message": {
    "role": "assistant",
    "content": "Hasil analisis..."
  },
  "usage": {
    "input_tokens": 0,
    "output_tokens": 0,
    "total_tokens": 0
  },
  "runtime": {
    "provider": "openai-codex",
    "model": "gpt-5.6-sol"
  }
}
```

